describe('Table Row Expansion', () => {
    beforeEach(() => {
        cy.visit('/table-list'); // Adjust the URL to your application
    });

    it('should expand a row to show nested details', () => {
        cy.get('.table-row').first().click(); // Assuming the rows have a class of 'table-row'
        cy.get('.nested-details').should('be.visible'); // Assuming nested details have a class of 'nested-details'
    });

    it('should collapse the row when clicked again', () => {
        cy.get('.table-row').first().click(); // Expand the row
        cy.get('.table-row').first().click(); // Collapse the row
        cy.get('.nested-details').should('not.be.visible'); // Ensure nested details are not visible
    });
});
